 */

// AscendC Sum reduction kernel — per-row reduction along last dimension
// Input:  x[M, N]  (float32 / float16 / bfloat16)
// Output: y[M]     (per-row sum, same dtype as input)
// Strategy: multi-core row distribution; fp16/bf16 cast to fp32 for reduction

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Sum Kernel
// =========================================================================

template <typename T>
class KernelSum {
public:
    __aicore__ inline KernelSum() {}

    __aicore__ inline void Init(
        AscendC::GlobalTensor<T> xGm,
        AscendC::GlobalTensor<T> yGm,
        uint32_t totalLength,
        uint32_t reductionSize,
        uint32_t rowsPerCore)
    {
        xGm_ = xGm;
        yGm_ = yGm;
        totalLength_ = totalLength;
        reductionSize_ = reductionSize;
        rowsPerCore_ = rowsPerCore;

        // Allocate input buffer in UB
        inpBuf_ = AscendC::TBuf<AscendC::TPosition::VECCALC>();
        inpBuf_.InitBuffer(inpTensor_, reductionSize_);

        // Allocate cast buffer (for fp16/bf16 → fp32)
        castBuf_ = AscendC::TBuf<AscendC::TPosition::VECCALC>();
        castBuf_.InitBuffer(castTensor_, reductionSize_);

        // Allocate reduce tmp buffer
        reduceTmpBuf_ = AscendC::TBuf<AscendC::TPosition::VECCALC>();
        // Reserve space for reduce; size computed conservatively
        reduceTmpBuf_.InitBuffer(reduceTmpTensor_, reductionSize_ * 4);

        // Allocate output scalar buffer
        outBuf_ = AscendC::TBuf<AscendC::TPosition::VECCALC>();
        outBuf_.InitBuffer(outTensor_, 1);
    }

    __aicore__ inline void Process(int32_t coreIdx)
    {
        uint32_t rowStart = static_cast<uint32_t>(coreIdx) * rowsPerCore_;
        uint32_t rowEnd = rowStart + rowsPerCore_;
        if (rowEnd > totalLength_) { rowEnd = totalLength_; }

        for (uint32_t r = rowStart; r < rowEnd; ++r) {
            ComputeOneRow(r);
        }
    }

private:
    __aicore__ inline void ComputeOneRow(uint32_t rowIdx)
    {
        // Load entire row from GM to UB
        LoadGmToUb(inpTensor_, xGm_[rowIdx * reductionSize_], reductionSize_);

        if constexpr (std::is_same_v<T, float>) {
            // Float32: reduce directly
            AscendC::ReduceSum<float, true>(
                outTensor_, inpTensor_, reduceTmpTensor_,
                static_cast<int32_t>(reductionSize_));
        } else {
            // Half / BFloat16: cast to float32, reduce, cast back
            AscendC::Cast(castTensor_, inpTensor_, AscendC::RoundMode::CAST_NONE,
                          reductionSize_);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::ReduceSum<float, true>(
                outTensor_, castTensor_, reduceTmpTensor_,
                static_cast<int32_t>(reductionSize_));

            AscendC::Cast(inpTensor_, outTensor_, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Write scalar result to output GM
        StoreUbToGm(yGm_[rowIdx], outTensor_, 1);
    }

    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<T> yGm_;
    uint32_t totalLength_;
    uint32_t reductionSize_;
    uint32_t rowsPerCore_;

    AscendC::LocalTensor<T> inpTensor_;
    AscendC::LocalTensor<float> castTensor_;
    AscendC::LocalTensor<uint8_t> reduceTmpTensor_;
    AscendC::LocalTensor<T> outTensor_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> inpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf_;
};

// =========================================================================
// Agent entry points
// =========================================================================

template <typename T>
__aicore__ inline void sum_kernel_entry(
    AscendC::GlobalTensor<T> xGm,
    AscendC::GlobalTensor<T> yGm,
    uint32_t totalLength,
    uint32_t reductionSize,
    uint32_t rowsPerCore,
    uint32_t usedCoreNum)
{
    int32_t coreIdx = AscendC::GetBlockIdx();
    if (coreIdx >= static_cast<int32_t>(usedCoreNum)) { return; }

    KernelSum<T> kernel;
    kernel.Init(xGm, yGm, totalLength, reductionSize, rowsPerCore);
    kernel.Process(coreIdx);
}

extern "C" __global__ __aicore__ void sum_kernel_fp32(
    AscendC::GlobalTensor<float> xGm,
    AscendC::GlobalTensor<float> yGm,
    uint32_t totalLength,
    uint32_t reductionSize,
    uint32_t rowsPerCore,
    uint32_t usedCoreNum)
{
    sum_kernel_entry<float>(xGm, yGm, totalLength, reductionSize, rowsPerCore, usedCoreNum);
}

extern "C" __global__ __aicore__ void sum_kernel_fp16(
    AscendC::GlobalTensor<half> xGm,
    AscendC::GlobalTensor<half> yGm,
    uint32_t totalLength,
    uint32_t reductionSize,
    uint32_t rowsPerCore,
    uint32_t usedCoreNum)
{
    sum_kernel_entry<half>(xGm, yGm, totalLength, reductionSize, rowsPerCore, usedCoreNum);
}

extern "C" __global__ __aicore__ void sum_kernel_bf16(
    AscendC::GlobalTensor<bfloat16_t> xGm,
    AscendC::GlobalTensor<bfloat16_t> yGm,
    uint32_t totalLength,
    uint32_t reductionSize,
    uint32_t rowsPerCore,
    uint32_t usedCoreNum)
{
    sum_kernel_entry<bfloat16_t>(xGm, yGm, totalLength, reductionSize, rowsPerCore, usedCoreNum);
}
