        if constexpr (std::is_same_v<T, float>) {
            // Float32: reduce directly
            AscendC::ReduceSum<float>(outTmpLocal_, inpLocal_, reduceTmpLocal_,
                                      static_cast<int32_t>(reductionSize_));
            AscendC::PipeBarrier<PIPE_V>();
            // Write scalar result to output GM
            StoreUbToGm(yGm_[rowIdx], outTmpLocal_, 1);
            AscendC::PipeBarrier<PIPE_MTE3>();
        } else {
            // Half / BFloat16: cast to float32 → reduce → cast back
            AscendC::Cast(castLocal_, inpLocal_, AscendC::RoundMode::CAST_NONE,
                          reductionSize_);
            AscendC::PipeBarrier<PIPE_V>();

