                                      static_cast<int32_t>(reductionSize_));
            AscendC::PipeBarrier<PIPE_V>();

            // Cast float scalar back to T
            AscendC::Cast(inpLocal_, outTmpLocal_, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::PipeBarrier<PIPE_V>();

