6	// Sum op_host — tiling calculation + EXEC_KERNEL_CMD launch
7	// Input:  x[M, N]  (float32 / float16 / bfloat16)
8	// Output: y[M]     (per-row sum)
9	
10	#include <algorithm>
11	#include <cstdint>
12	
13	#include <torch/extension.h>
14	#include <torch/library.h>
15	
16	#include "torch_kernel_helper.h"
17	#include "tiling/platform/platform_ascendc.h"
18	
19	#include "aclrtlaunch_sum_kernel_fp32.h"
20	#include "aclrtlaunch_sum_kernel_fp16.h"
21	#include "aclrtlaunch_sum_kernel_bf16.h"
22	
23	namespace ascend_kernel {
24	
25	at::Tensor sum(const at::Tensor &x, int64_t dim, bool keepdim)
26	{
27	    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
28	    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
29	                    x.scalar_type() == at::kBFloat16,
30	                "x must be float32, float16, or bfloat16");
31	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
32	
33	    // Normalize dim
34	    int64_t ndim = x.dim();
35	    if (dim < 0) { dim += ndim; }
36	    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
37	
38	    // Compute M (non-reduction elements product) and N (reduction dim size)
39	    int64_t M = 1;
40	    for (int64_t d = 0; d < ndim; ++d) {
41	        if (d != dim) { M *= x.size(d); }
42	    }
43	    int64_t N = x.size(dim);
44	
45	    int32_t iM = static_cast<int32_t>(M);
46	    int32_t iN = static_cast<int32_t>(N);
47	
48	    // Get AIV core count from platform API
49	    int32_t aivCoreNum = static_cast<int32_t>(
50	        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAiv());
51	    if (aivCoreNum <= 0) { aivCoreNum = 16; }  // fallback
52	
53	    int32_t usedCoreNum = std::min<int32_t>(aivCoreNum, std::max<int32_t>(1, iM));
54	    int32_t rowsPerCore = (iM + usedCoreNum - 1) / usedCoreNum;
55	
56	    // Output shape: remove reduction dim (or keep as size 1 if keepdim)
57	    std::vector<int64_t> outShape;
58	    if (keepdim) {
59	        for (int64_t d = 0; d < ndim; ++d) {
60	            outShape.push_back((d == dim) ? 1 : x.size(d));
61	        }
62	    } else {
63	        for (int64_t d = 0; d < ndim; ++d) {
64	            if (d != dim) { outShape.push_back(x.size(d)); }
65	        }
66	    }
67	
68	    at::Tensor y = at::empty(outShape, x.options());
69	
70	    // All tiling params as left values (EXEC_KERNEL_CMD requirement)
71	    uint32_t totalLength = static_cast<uint32_t>(iM);
72	    uint32_t reductionSize = static_cast<uint32_t>(iN);
73	    uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCore);
74	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
75	
76	    // Dispatch by dtype
77	    if (x.scalar_type() == at::kFloat) {
78	        EXEC_KERNEL_CMD(sum_kernel_fp32, blockDim,
79	                        x, y, totalLength, reductionSize, rowsPerCoreU32, usedCoreNum);
80	    } else if (x.scalar_type() == at::kHalf) {
81	        EXEC_KERNEL_CMD(sum_kernel_fp16, blockDim,
82	                        x, y, totalLength, reductionSize, rowsPerCoreU32, usedCoreNum);
83	    } else if (x.scalar_type() == at::kBFloat16) {
84	        EXEC_KERNEL_CMD(sum_kernel_bf16, blockDim,
85	                        x, y, totalLength, reductionSize, rowsPerCoreU32, usedCoreNum);
86	    }
87	
88	    return y;
89	}
90	
91	}  // namespace ascend_kernel
