        // Use advanced ReduceSum with AR pattern on shape {1, N}
        // This reduces along the last dimension (N) to a scalar
        uint32_t shape[2] = {1U, static_cast<uint32_t>(reductionSize_)};

        if constexpr (std::is_same_v<T, float>) {
            AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
                outTmpLocal_, inpLocal_, reduceTmpLocal_, shape, true);
            AscendC::PipeBarrier<PIPE_V>();
            StoreUbToGm(yGm_[rowIdx], outTmpLocal_, 1);
            AscendC::PipeBarrier<PIPE_MTE3>();
        } else {
            // fp16/bf16: cast to float32 first
            AscendC::Cast(castLocal_, inpLocal_, AscendC::RoundMode::CAST_NONE,
