// AscendC Sum reduction kernel — per-row reduction along last dimension
// Input:  x[M, N]  (float32 / float16 / bfloat16)
// Output: y[M]     (per-row sum, same dtype as input)
// Strategy: multi-core row distribution; fp16/bf16 cast to fp32 for reduction
// Uses scalar accumulation to avoid vector API alignment constraints

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Sum Kernel
// =========================================================================

template <typename T>
class KernelSum {
public:
    __aicore__ inline KernelSum() {}

    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR yGm,
        uint32_t totalLength, uint32_t reductionSize, uint32_t rowsPerCore,
        uint32_t usedCoreNum)
    {
        totalLength_ = totalLength;
        reductionSize_ = reductionSize;
        rowsPerCore_ = rowsPerCore;
        usedCoreNum_ = usedCoreNum;

        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(xGm),
                             static_cast<uint64_t>(totalLength) * reductionSize);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yGm),
                             static_cast<uint64_t>(totalLength));

        if ASCEND_IS_AIV {
            pipe_.InitBuffer(inpBuf_, reductionSize * sizeof(T));
            pipe_.InitBuffer(castBuf_, reductionSize * sizeof(float));
            pipe_.InitBuffer(tmpBuf_, 16 * sizeof(float));

            inpLocal_ = inpBuf_.Get<T>();
            castLocal_ = castBuf_.Get<float>();
            tmpLocal_ = tmpBuf_.Get<float>();
        }
    }

    __aicore__ inline void Process(int32_t coreIdx)
    {
        if ASCEND_IS_AIV {
            uint32_t rowStart = static_cast<uint32_t>(coreIdx) * rowsPerCore_;
            uint32_t rowEnd = rowStart + rowsPerCore_;
            if (rowEnd > totalLength_) { rowEnd = totalLength_; }

            for (uint32_t r = rowStart; r < rowEnd; ++r) {
                ComputeOneRow(r);
            }
        }
    }

private:
    __aicore__ inline void ComputeOneRow(uint32_t rowIdx)
    {
        // Load entire row from GM to UB
        LoadGmToUb(inpLocal_, xGm_[rowIdx * reductionSize_], reductionSize_);
        AscendC::PipeBarrier<PIPE_MTE2>();

        if constexpr (std::is_same_v<T, float>) {
            // Float32: scalar accumulation
            float sum = 0.0f;
            for (uint32_t i = 0; i < reductionSize_; ++i) {
                sum += inpLocal_.GetValue(i);
            }
            tmpLocal_.SetValue(0, sum);
            AscendC::PipeBarrier<PIPE_V>();
            StoreUbToGm(yGm_[rowIdx], tmpLocal_, 1);
            AscendC::PipeBarrier<PIPE_MTE3>();
        } else {
            // fp16/bf16: cast to float32, scalar accumulate, cast back
            AscendC::Cast(castLocal_, inpLocal_, AscendC::RoundMode::CAST_NONE,
                          reductionSize_);
            AscendC::PipeBarrier<PIPE_V>();

            float sum = 0.0f;
            for (uint32_t i = 0; i < reductionSize_; ++i) {
                sum += castLocal_.GetValue(i);
            }
            tmpLocal_.SetValue(0, sum);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Cast(inpLocal_, tmpLocal_, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::PipeBarrier<PIPE_V>();

            StoreUbToGm(yGm_[rowIdx], inpLocal_, 1);
            AscendC::PipeBarrier<PIPE_MTE3>();
        }
    }

    AscendC::TPipe pipe_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> inpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    AscendC::LocalTensor<T> inpLocal_;
    AscendC::LocalTensor<float> castLocal_;
    AscendC::LocalTensor<float> tmpLocal_;

    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<T> yGm_;
    uint32_t totalLength_;
    uint32_t reductionSize_;
    uint32_t rowsPerCore_;
    uint32_t usedCoreNum_;
};

