6	// AscendC Sum reduction kernel — per-row reduction along last dimension
7	// Input:  x[M, N]  (float32 / float16 / bfloat16)
8	// Output: y[M]     (per-row sum, same dtype as input)
9	// Strategy: multi-core row distribution; fp16/bf16 cast to fp32 for reduction
10	// Uses scalar accumulation to avoid vector API alignment constraints
11	
12	#include "kernel_operator.h"
13	
14	constexpr int32_t BUFFER_NUM = 1;
15	
16	// ---------------------------------------------------------------------------
17	// Helpers
18	// ---------------------------------------------------------------------------
19	
20	template <typename T>
21	__aicore__ inline void LoadGmToUb(
22	    AscendC::LocalTensor<T> &dst,
23	    AscendC::GlobalTensor<T> src,
24	    uint32_t count)
25	{
26	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
27	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
28	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
29	}
30	
31	template <typename T>
32	__aicore__ inline void StoreUbToGm(
33	    AscendC::GlobalTensor<T> dst,
34	    AscendC::LocalTensor<T> &src,
35	    uint32_t count)
36	{
37	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
38	    AscendC::DataCopyPad(dst, src, copyParams);
39	}
40	
41	// =========================================================================
42	// Sum Kernel
43	// =========================================================================
44	
45	template <typename T>
46	class KernelSum {
47	public:
48	    __aicore__ inline KernelSum() {}
49	
50	    __aicore__ inline void Init(
51	        GM_ADDR xGm, GM_ADDR yGm,
52	        uint32_t totalLength, uint32_t reductionSize, uint32_t rowsPerCore,
53	        uint32_t usedCoreNum)
54	    {
55	        totalLength_ = totalLength;
56	        reductionSize_ = reductionSize;
57	        rowsPerCore_ = rowsPerCore;
58	        usedCoreNum_ = usedCoreNum;
59	
60	        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(xGm),
61	                             static_cast<uint64_t>(totalLength) * reductionSize);
62	        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yGm),
63	                             static_cast<uint64_t>(totalLength));
64	
65	        if ASCEND_IS_AIV {
66	            // Compute padded size for 32B alignment
67	            uint32_t elemsPerAlign = 32U / static_cast<uint32_t>(sizeof(T));
68	            uint32_t paddedSize = CeilDivU32(reductionSize_, elemsPerAlign) * elemsPerAlign;
69	            pipe_.InitBuffer(inpBuf_, paddedSize * sizeof(T));
70	
71	            uint32_t floatElemsPerAlign = 32U / static_cast<uint32_t>(sizeof(float));
72	            uint32_t floatPaddedSize = CeilDivU32(paddedSize, floatElemsPerAlign) * floatElemsPerAlign;
73	            pipe_.InitBuffer(castBuf_, floatPaddedSize * sizeof(float));
74	            pipe_.InitBuffer(tmpBuf_, floatPaddedSize * sizeof(float));
75	
76	            inpLocal_ = inpBuf_.Get<T>();
77	            castLocal_ = castBuf_.Get<float>();
78	            tmpLocal_ = tmpBuf_.Get<float>();
79	        }
80	    }
81	
82	    __aicore__ inline void Process(int32_t coreIdx)
83	    {
84	        if ASCEND_IS_AIV {
85	            uint32_t rowStart = static_cast<uint32_t>(coreIdx) * rowsPerCore_;
86	            uint32_t rowEnd = rowStart + rowsPerCore_;
87	            if (rowEnd > totalLength_) { rowEnd = totalLength_; }
88	
89	            for (uint32_t r = rowStart; r < rowEnd; ++r) {
90	                ComputeOneRow(r);
91	            }
92	        }
93	    }
94	
95	private:
96	    __aicore__ inline void ComputeOneRow(uint32_t rowIdx)
97	    {
98	        // Load entire row from GM to UB
99	        LoadGmToUb(inpLocal_, xGm_[rowIdx * reductionSize_], reductionSize_);
100	        AscendC::PipeBarrier<PIPE_MTE2>();
101	
102	        if constexpr (std::is_same_v<T, float>) {
103	            // Float32: scalar accumulation
104	            float sum = 0.0f;
105	            for (uint32_t i = 0; i < reductionSize_; ++i) {
106	                sum += inpLocal_.GetValue(i);
107	            }
108	            tmpLocal_.SetValue(0, sum);
109	            AscendC::PipeBarrier<PIPE_V>();
110	            StoreUbToGm(yGm_[rowIdx], tmpLocal_, 1);
111	            AscendC::PipeBarrier<PIPE_MTE3>();
112	        } else {
113	            // fp16/bf16: cast to float32, scalar accumulate, cast back
114	            AscendC::Cast(castLocal_, inpLocal_, AscendC::RoundMode::CAST_NONE,
115	                          reductionSize_);
116	            AscendC::PipeBarrier<PIPE_V>();
117	
118	            float sum = 0.0f;
119	            for (uint32_t i = 0; i < reductionSize_; ++i) {
120	                sum += castLocal_.GetValue(i);
121	            }
122	
123	            // Fill tmp buffer with sum for aligned Cast
124	            uint32_t elemsPerAlign = 32U / static_cast<uint32_t>(sizeof(T));
125	            uint32_t paddedSize = CeilDivU32(reductionSize_, elemsPerAlign) * elemsPerAlign;
126	            uint32_t floatElemsPerAlign = 32U / static_cast<uint32_t>(sizeof(float));
127	            uint32_t castCount = CeilDivU32(paddedSize, floatElemsPerAlign) * floatElemsPerAlign;
128	
129	            for (uint32_t i = 0; i < castCount; ++i) {
130	                tmpLocal_.SetValue(i, sum);
131	            }
132	            AscendC::PipeBarrier<PIPE_V>();
133	
134	            AscendC::Cast(inpLocal_, tmpLocal_, AscendC::RoundMode::CAST_ROUND, castCount);
135	            AscendC::PipeBarrier<PIPE_V>();
136	
137	            StoreUbToGm(yGm_[rowIdx], inpLocal_, 1);
138	            AscendC::PipeBarrier<PIPE_MTE3>();
139	        }
140	    }
141	
142	    AscendC::TPipe pipe_;
143	    AscendC::TBuf<AscendC::TPosition::VECCALC> inpBuf_;
144	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
145	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
146	
147	    AscendC::LocalTensor<T> inpLocal_;
148	    AscendC::LocalTensor<float> castLocal_;
149	    AscendC::LocalTensor<float> tmpLocal_;
150	
151	    AscendC::GlobalTensor<T> xGm_;
152	    AscendC::GlobalTensor<T> yGm_;
153	    uint32_t totalLength_;
154	    uint32_t reductionSize_;
155	    uint32_t rowsPerCore_;
156	    uint32_t usedCoreNum_;
157	};
