// Sum op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Handles dtype conversion: fp16/bf16 inputs are upcast to float32 on host,
// kernel only handles float32, output is cast back to original dtype.

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_sum_kernel_fp32.h"

namespace ascend_kernel {

at::Tensor sum(const at::Tensor &x, int64_t dim, bool keepdim)
{
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                    x.scalar_type() == at::kBFloat16,
                "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Normalize dim
    int64_t ndim = x.dim();
    if (dim < 0) { dim += ndim; }
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    // Kernel only supports reduction along the last dimension
    TORCH_CHECK(dim == ndim - 1, "Only last-dimension reduction is supported");

    // Compute M (non-reduction elements product) and N (reduction dim size)
    int64_t M = 1;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dim) { M *= x.size(d); }
    }
    int64_t N = x.size(dim);

    int32_t iM = static_cast<int32_t>(M);
    int32_t iN = static_cast<int32_t>(N);

    // Get AIV core count from platform API
    int32_t aivCoreNum = static_cast<int32_t>(
        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAiv());
    if (aivCoreNum <= 0) { aivCoreNum = 16; }  // fallback

    int32_t usedCoreNum = std::min<int32_t>(aivCoreNum, std::max<int32_t>(1, iM));
    int32_t rowsPerCore = (iM + usedCoreNum - 1) / usedCoreNum;

    // Output shape: remove reduction dim (or keep as size 1 if keepdim)
    std::vector<int64_t> outShape;
    if (keepdim) {
        for (int64_t d = 0; d < ndim; ++d) {
            outShape.push_back((d == dim) ? 1 : x.size(d));
        }
    } else {
        for (int64_t d = 0; d < ndim; ++d) {
            if (d != dim) { outShape.push_back(x.size(d)); }
        }
    }

    // Convert input to float32 if needed (kernel only handles float32)
    at::Tensor x_f32 = x;
    at::ScalarType origDtype = x.scalar_type();
    if (origDtype != at::kFloat) {
        x_f32 = x.to(at::kFloat);
    }

    at::Tensor y_f32 = at::empty(outShape, x_f32.options());

    // All tiling params as left values (EXEC_KERNEL_CMD requirement)
    uint32_t totalLength = static_cast<uint32_t>(iM);
    uint32_t reductionSize = static_cast<uint32_t>(iN);
    uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCore);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(sum_kernel_fp32, blockDim,
                    x_f32, y_f32, totalLength, reductionSize, rowsPerCoreU32, usedCoreNum);

    // Convert output back to original dtype if needed
    if (origDtype != at::kFloat) {
        return y_f32.to(origDtype);
    }
    return y_f32;
}

}  // namespace ascend_kernel
